int32_t UIContentImpl::CreateModalUIExtension(
    const AAFwk::Want& want, const ModalUIExtensionCallbacks& callbacks, const ModalUIExtensionConfig& config)
{
    auto container = Platform::AceContainer::GetContainer(instanceId_);
    CHECK_NULL_RETURN(container, 0);
    ContainerScope scope(instanceId_);
    auto taskExecutor = Container::CurrentTaskExecutor();
    CHECK_NULL_RETURN(taskExecutor, 0);
    int32_t sessionId = 0;
    taskExecutor->PostSyncTask(
        [container, &sessionId, want, callbacks = callbacks, config = config, window = window_,
            instanceId = instanceId_]() {
            auto flag = want.GetBoolParam(USE_GLOBAL_UICONTENT, false);
            if (flag && CreateGlobalModalUIExtension(want, sessionId, callbacks, config, instanceId, window)) {
                return;
            }

            auto pipeline = AceType::DynamicCast<NG::PipelineContext>(container->GetPipelineContext());
            CHECK_NULL_VOID(pipeline);
            auto overlay = pipeline->GetOverlayManager();
            CHECK_NULL_VOID(overlay);
            sessionId = overlay->CreateModalUIExtension(want, callbacks, config);
        },
        TaskExecutor::TaskType::UI, "ArkUICreateModalUIExtension");
    TAG_LOGI(AceLogTag::ACE_UIEXTENSIONCOMPONENT,
        "[%{public}s][%{public}s][%{public}d]: create modal page, "
        "sessionId=%{public}d, isProhibitBack=%{public}d, isAsyncModalBinding=%{public}d, "
        "isAllowedBeCovered=%{public}d, prohibitedRemoveByRouter=%{public}d, "
        "isAllowAddChildBelowModalUec=%{public}d, prohibitedRemoveByNavigation=%{public}d",
        bundleName_.c_str(), moduleName_.c_str(), instanceId_, sessionId, config.isProhibitBack,
        config.isAsyncModalBinding, config.isAllowedBeCovered, config.prohibitedRemoveByRouter,
        config.isAllowAddChildBelowModalUec, config.prohibitedRemoveByNavigation);
    return sessionId;
}

void UIContentImpl::CloseModalUIExtension(int32_t sessionId)
{
    TAG_LOGI(AceLogTag::ACE_UIEXTENSIONCOMPONENT,
        "[%{public}s][%{public}s][%{public}d]: close modal page, "
        "sessionId=%{public}d",
        bundleName_.c_str(), moduleName_.c_str(), instanceId_, sessionId);
    if (sessionId == 0) {
        LOGW("UIExtension refuse to close modal page");
        return;
    }
    auto container = Platform::AceContainer::GetContainer(instanceId_);
    CHECK_NULL_VOID(container);
    ContainerScope scope(instanceId_);
    auto taskExecutor = Container::CurrentTaskExecutor();
    CHECK_NULL_VOID(taskExecutor);
    taskExecutor->PostTask(
        [container, sessionId]() {
            if (CloseGlobalModalUIExtension(container->GetInstanceId(), sessionId, "")) {
                return;
            }

            auto pipeline = AceType::DynamicCast<NG::PipelineContext>(container->GetPipelineContext());
            CHECK_NULL_VOID(pipeline);
            auto overlay = pipeline->GetOverlayManager();
            CHECK_NULL_VOID(overlay);
            overlay->CloseModalUIExtension(sessionId);
        },
        TaskExecutor::TaskType::UI, "ArkUICloseModalUIExtension");

taskExecutor->PostTask(
    [weak, code, want, sessionType, callSessionId] () {
        auto pattern = weak.Upgrade();
        CHECK_NULL_VOID(pattern);
        if (callSessionId != pattern->GetSessionId()) {
            TAG_LOGW(AceLogTag::ACE_UIEXTENSIONCOMPONENT,
                "transferAbilityResultFunc_: The callSessionId(%{public}d)"
                    " is inconsistent with the curSession(%{public}d)",
                callSessionId, pattern->GetSessionId());
                return;
        }

        if (sessionType == SessionType::UI_EXTENSION_ABILITY
            && pattern->IsCompatibleOldVersion()) {
            pattern->FireOnResultCallback(code, want);
        } else {
            pattern->FireOnTerminatedCallback(code, MakeRefPtr<WantWrapOhos>(want));
        }
    }, TaskExecutor::TaskType::UI, "ArkUIUIExtensionTransferAbilityResult");

void UIExtensionPattern::FireOnReleaseCallback(int32_t releaseCode)
{
    UIEXT_LOGI("OnRelease the state is changing from '%{public}s' to 'DESTRUCTION' and releaseCode = %{public}d.",
        ToString(state_), releaseCode);
    state_ = AbilityState::DESTRUCTION;
    SetEventProxyFlag(static_cast<int32_t>(EventProxyFlag::EVENT_NONE));
    if (onReleaseCallback_) {
        onReleaseCallback_(releaseCode);
    }
    // Release the session.
    if (sessionWrapper_ && sessionWrapper_->IsSessionValid()) {
        sessionWrapper_->OnReleaseDone();
    }

void UIExtensionPattern::FireOnErrorCallback(int32_t code, const std::string& name, const std::string& message)
{
    // 1. As long as the error occurs, the host believes that UIExtensionAbility has been killed.
    UIEXT_LOGI("OnError the state is changing from '%{public}s' to 'NONE', errorCode = %{public}d.",
        ToString(state_), code);
    state_ = AbilityState::NONE;
    SetEventProxyFlag(static_cast<int32_t>(EventProxyFlag::EVENT_NONE));
    // Release the session.
    if (sessionWrapper_ && sessionWrapper_->IsSessionValid()) {
        if (!IsShowPlaceholder()) {
            auto host = GetHost();
            CHECK_NULL_VOID(host);
            host->RemoveChildAtIndex(0);
            host->MarkDirtyNode(PROPERTY_UPDATE_MEASURE);
        }
        if (name.compare("extension_node_transparent") != 0) {
            sessionWrapper_->NotifyDestroy(false);
            sessionWrapper_->DestroySession();
        }
    }
    if (onErrorCallback_) {
        ContainerScope scope(instanceId_);
        onErrorCallback_(code, name, message);
        return;
    }
    lastError_ = { code, name, message };
}

void UIExtensionPattern::SetOnResultCallback(const std::function<void(int32_t, const AAFwk::Want&)>&& callback)
{
    onResultCallback_ = std::move(callback);
}

void UIExtensionPattern::FireOnResultCallback(int32_t code, const AAFwk::Want& want)
{
    UIEXT_LOGI("OnResult the state is changing from '%{public}s' to 'DESTRUCTION'.", ToString(state_));
    if (onResultCallback_ && (state_ != AbilityState::DESTRUCTION)) {
        ContainerScope scope(instanceId_);
        onResultCallback_(code, want);
    }
    state_ = AbilityState::DESTRUCTION;

